{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver surveys the ruined city from a high window.",
      "visual_description": "A shattered window frame overlooks a crumbled royal city. The glass diver's helmet reflects the broken skyline and distant castle gates.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer unfolds a stained map under flickering lamplight.",
      "visual_description": "In a dark alcove, Mara spreads a parchment map across a stone table, her brass compass glinting. The oracle lamp sits nearby, its single eye casting a warm glow.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scampers ahead through rubble and rust.",
      "visual_description": "The small metal fox picks its way over broken cobblestones and twisted metal, its key-wind tail ticking softly, blue glass eyes scanning for danger.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver swims through a mirror into a cursed tower.",
      "visual_description": "Surface of a tall mirror ripples like water as the glass diver steps through, coat reflecting the tower's interior: faded tapestries and a spiral stair.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Mara marks a safe path past a fallen gate.",
      "visual_description": "Mara kneels beside a massive iron gate lying flat, inking a route on her map. The oracle lamp hovers nearby, casting light on the rusted hinges.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "The sleeping tax collector snores on a ledger pile in a ruined plaza.",
      "visual_description": "Amid scattered papers and broken statues, the tax collector sleeps with a ledger as a pillow, stamped receipts stuck to sleeves. A tattered royal banner droops overhead.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "The tin fox discovers a secret passage beneath a well.",
      "visual_description": "The fox scratches at an iron grating beside an old well, revealing stone steps descending into darkness. Blue eyes reflect faint movement below.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The glass diver peers through a frost-covered window into an armored patrol.",
      "visual_description": "Through a window thick with frost, the diver sees figures in ornate armor marching in the street, their helmets catching dim light from a brazier.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Mara consults the oracle lamp about a magical door.",
      "visual_description": "Before a door covered in glowing runes, Mara holds up the lamp. The flame's eye narrows, casting shifting shadows as it speaks a warning.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The glass diver slips through a mirror inside the tower to bypass the door.",
      "visual_description": "Inside a dusty chamber, the diver steps into a full-length mirror, coat dissolving into silver before reappearing in a hallway beyond the runed door.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector wakes briefly to stamp a map.",
      "visual_description": "Jolted by a collapse of papers, the tax collector sleepily stamps Mara's map with a red seal, then drops back onto the ledger pillow.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox reports back to Mara with a clatter of gears.",
      "visual_description": "The fox returns to Mara, its head gesturing toward the well. Tiny gears click as it points with a paw, blue eyes bright.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The glass diver finds a hidden chamber filled with old royal banners.",
      "visual_description": "A circular room with faded banners hanging from the ceiling, their colors bleached. Dust motes drift in a single beam of light as the diver steps in.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Mara leads the group toward the cursed tower, the oracle lamp lighting the way.",
      "visual_description": "Mara walks through a narrow alley, the lamp held high. The tin fox follows at her heels. Broken windows reflect their passage.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver escorts a frightened townsman past a patrol.",
      "visual_description": "The diver helps a trembling figure in plain clothes duck behind a collapsed cart as armored footsteps echo nearby. The diver's helmet shows the patrol's reflection.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "The sleeping tax collector is left behind, still dozing on the plaza.",
      "visual_description": "The tax collector remains curled on the ledger pile as the others move out. A banner flutters above. No one looks back.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The group reaches the escape bridge, but a magical barrier blocks the way.",
      "visual_description": "A stone bridge arches over a dry riverbed. A shimmering wall of light bars the far end. The oracle lamp flares as it examines the barrier.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The glass diver swims through a reflection on the bridge, disabling the barrier.",
      "visual_description": "The diver steps into a puddle's reflection, emerges on the other side, and shatters a glowing crystal on the barrier's edge. The light fades, and the group crosses to safety.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    }
  ]
}

